    16→
    17→/// Converts a blob ssz List object to an array to be used with the kzg
    18→/// crypto library.
    19→fn ssz_blob_to_crypto_blob<E: EthSpec>(blob: &Blob<E>) -> Result<KzgBlob, KzgError> {
    20→    KzgBlob::from_bytes(blob.as_ref()).map_err(Into::into)
    21→}
    22→
    23→fn ssz_blob_to_crypto_blob_boxed<E: EthSpec>(blob: &Blob<E>) -> Result<Box<KzgBlob>, KzgError> {
    24→    ssz_blob_to_crypto_blob::<E>(blob).map(Box::new)
    25→}
    26→
    27→/// Converts a cell ssz List object to an array to be used with the kzg
    28→/// crypto library.
    29→fn ssz_cell_to_crypto_cell<E: EthSpec>(cell: &Cell<E>) -> Result<KzgCellRef<'_>, KzgError> {
    30→    let cell_bytes: &[u8] = cell.as_ref();
    31→    cell_bytes
    32→        .try_into()
    33→        .map_err(|e| KzgError::InconsistentArrayLength(format!("expected cell to have size BYTES_PER_CELL. This should be guaranteed by the `FixedVector` type: {e:?}")))
    34→}
    35→
    36→/// Validate a single blob-commitment-proof triplet from a `BlobSidecar`.
    37→pub fn validate_blob<E: EthSpec>(
    38→    kzg: &Kzg,
    39→    blob: &Blob<E>,
    40→    kzg_commitment: KzgCommitment,
    41→    kzg_proof: KzgProof,
    42→) -> Result<(), KzgError> {
    43→    let _timer = crate::metrics::start_timer(&crate::metrics::KZG_VERIFICATION_SINGLE_TIMES);
    44→    let kzg_blob = ssz_blob_to_crypto_blob_boxed::<E>(blob)?;
    45→    kzg.verify_blob_kzg_proof(&kzg_blob, kzg_commitment, kzg_proof)
    46→}
    47→
    48→/// Validate a batch of `DataColumnSidecar`.
    49→pub fn validate_data_columns<'a, E: EthSpec, I>(
    50→    kzg: &Kzg,
    51→    data_column_iter: I,
    52→) -> Result<(), (Option<u64>, KzgError)>
    53→where
    54→    I: Iterator<Item = &'a Arc<DataColumnSidecar<E>>> + Clone,
    55→{
    56→    let mut cells = Vec::new();
    57→    let mut proofs = Vec::new();
    58→    let mut column_indices = Vec::new();
    59→    let mut commitments = Vec::new();
    60→
    61→    for data_column in data_column_iter {
    62→        let col_index = data_column.index;
    63→
    64→        if data_column.column.is_empty() {
    65→            return Err((Some(col_index), KzgError::KzgVerificationFailed));
    66→        }
    67→
    68→        for cell in &data_column.column {
    69→            cells.push(ssz_cell_to_crypto_cell::<E>(cell).map_err(|e| (Some(col_index), e))?);
    70→            column_indices.push(col_index);
    71→        }
    72→
    73→        for &proof in &data_column.kzg_proofs {
    74→            proofs.push(Bytes48::from(proof));
    75→        }
    76→
    77→        for &commitment in &data_column.kzg_commitments {
    78→            commitments.push(Bytes48::from(commitment));
    79→        }
    80→
    81→        let expected_len = column_indices.len();
    82→
    83→        // We make this check at each iteration so that the error is attributable to a specific column
    84→        if cells.len() != expected_len
    85→            || proofs.len() != expected_len
    86→            || commitments.len() != expected_len
    87→        {
    88→            return Err((
    89→                Some(col_index),
    90→                KzgError::InconsistentArrayLength("Invalid data column".to_string()),
    91→            ));
    92→        }
    93→    }
    94→
    95→    kzg.verify_cell_proof_batch(&cells, &proofs, column_indices, &commitments)
    96→}
    97→
    98→/// Validate a batch of blob-commitment-proof triplets from multiple `BlobSidecars`.
    99→pub fn validate_blobs<E: EthSpec>(
   100→    kzg: &Kzg,
   101→    expected_kzg_commitments: &[KzgCommitment],
   102→    blobs: Vec<&Blob<E>>,
   103→    kzg_proofs: &[KzgProof],
   104→) -> Result<(), KzgError> {
   105→    let _timer = crate::metrics::start_timer(&crate::metrics::KZG_VERIFICATION_BATCH_TIMES);
   106→    let blobs = blobs
   107→        .into_iter()
   108→        .map(|blob| ssz_blob_to_crypto_blob::<E>(blob))
   109→        .collect::<Result<Vec<_>, KzgError>>()?;
   110→
   111→    kzg.verify_blob_kzg_proof_batch(&blobs, expected_kzg_commitments, kzg_proofs)
   112→}
   113→
   114→/// Compute the kzg proof given an ssz blob and its kzg commitment.
   115→pub fn compute_blob_kzg_proof<E: EthSpec>(
   116→    kzg: &Kzg,
   117→    blob: &Blob<E>,
   118→    kzg_commitment: KzgCommitment,
   119→) -> Result<KzgProof, KzgError> {
   120→    let kzg_blob = ssz_blob_to_crypto_blob_boxed::<E>(blob)?;
   121→    kzg.compute_blob_kzg_proof(&kzg_blob, kzg_commitment)
   122→}
   123→
   124→/// Compute the kzg commitment for a given blob.
   125→pub fn blob_to_kzg_commitment<E: EthSpec>(
   126→    kzg: &Kzg,
   127→    blob: &Blob<E>,
   128→) -> Result<KzgCommitment, KzgError> {
   129→    let kzg_blob = ssz_blob_to_crypto_blob_boxed::<E>(blob)?;
   130→    kzg.blob_to_kzg_commitment(&kzg_blob)
   131→}
   132→
   133→/// Compute the kzg proof for a given blob and an evaluation point z.
   134→pub fn compute_kzg_proof<E: EthSpec>(
   135→    kzg: &Kzg,
   136→    blob: &Blob<E>,
   137→    z: Hash256,
   138→) -> Result<(KzgProof, Hash256), KzgError> {
   139→    let z = z.0.into();
   140→    let kzg_blob = ssz_blob_to_crypto_blob_boxed::<E>(blob)?;
   141→    kzg.compute_kzg_proof(&kzg_blob, &z)
   142→        .map(|(proof, z)| (proof, Hash256::from_slice(&z.to_vec())))
   143→}
   144→
   145→/// Verify a `kzg_proof` for a `kzg_commitment` that evaluating a polynomial at `z` results in `y`
   146→pub fn verify_kzg_proof<E: EthSpec>(
   147→    kzg: &Kzg,
   148→    kzg_commitment: KzgCommitment,
   149→    kzg_proof: KzgProof,
   150→    z: Hash256,
   151→    y: Hash256,
   152→) -> Result<bool, KzgError> {
   153→    kzg.verify_kzg_proof(kzg_commitment, &z.0.into(), &y.0.into(), kzg_proof)
   154→}
