   156→/// Build data column sidecars from a signed beacon block and its blobs.
   157→#[instrument(skip_all, level = "debug", fields(blob_count = blobs.len()))]
   158→pub fn blobs_to_data_column_sidecars<E: EthSpec>(
   159→    blobs: &[&Blob<E>],
   160→    cell_proofs: Vec<KzgProof>,
   161→    block: &SignedBeaconBlock<E>,
   162→    kzg: &Kzg,
   163→    spec: &ChainSpec,
   164→) -> Result<DataColumnSidecarList<E>, DataColumnSidecarError> {
   165→    if blobs.is_empty() {
   166→        return Ok(vec![]);
   167→    }
   168→
   169→    let kzg_commitments = block
   170→        .message()
   171→        .body()
   172→        .blob_kzg_commitments()
   173→        .map_err(|_err| DataColumnSidecarError::PreDeneb)?;
   174→    let kzg_commitments_inclusion_proof = block.message().body().kzg_commitments_merkle_proof()?;
   175→    let signed_block_header = block.signed_block_header();
   176→
   177→    let proof_chunks = cell_proofs
   178→        .chunks_exact(E::number_of_columns())
   179→        .collect::<Vec<_>>();
   180→
   181→    // NOTE: assumes blob sidecars are ordered by index
   182→    let zipped: Vec<_> = blobs.iter().zip(proof_chunks).collect();
   183→    let blob_cells_and_proofs_vec = zipped
   184→        .into_par_iter()
   185→        .map(|(blob, proofs)| {
   186→            let blob = blob.as_ref().try_into().map_err(|e| {
   187→                KzgError::InconsistentArrayLength(format!(
   188→                    "blob should have a guaranteed size due to FixedVector: {e:?}"
   189→                ))
   190→            })?;
   191→
   192→            kzg.compute_cells(blob).and_then(|cells| {
   193→                let proofs = proofs.try_into().map_err(|e| {
   194→                    KzgError::InconsistentArrayLength(format!(
   195→                        "proof chunks should have exactly `number_of_columns` proofs: {e:?}"
   196→                    ))
   197→                })?;
   198→                Ok((cells, proofs))
   199→            })
   200→        })
   201→        .collect::<Result<Vec<_>, KzgError>>()?;
   202→
   203→    build_data_column_sidecars(
   204→        kzg_commitments.clone(),
   205→        kzg_commitments_inclusion_proof,
   206→        signed_block_header,
   207→        blob_cells_and_proofs_vec,
   208→        spec,
   209→    )
   210→    .map_err(DataColumnSidecarError::BuildSidecarFailed)
   211→}
